import { useEffect, useRef, useState } from 'react';
import { boardCode, parseBoardCode, SEED_MAX } from '../deck.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { Bracket } from './Bracket.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { TournamentPlay } from './TournamentPlay.tsx';
import { decodeTournament, encodeTournament, TOURNAMENT_MAX_BYTES } from './format.ts';
import { nameError } from './names.ts';
import {
  createTournament,
  finishTurn,
  matchRound,
  nextMatch,
  nextTurn,
  startTurn,
  TournamentPhase,
  turnIndex,
} from './rules.ts';
import { useHistory } from './use-history.ts';
import type { Result, TournamentState } from './rules.ts';
import type { TurnExport } from './TournamentPlay.tsx';
import type { TournamentDocument } from './format.ts';
import './tournament.css';

interface TournamentProps {
  back(): void;
  publish(text: string): void;
  confirm(action: () => void): void;
}

export function Tournament({ back, publish, confirm }: TournamentProps) {
  const [names, setNames] = useState<readonly string[]>(['', '', '', '']);
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const [snapshot, setSnapshot] = useState<string | null>(null);
  const [json, setJson] = useState('');
  const [notice, setNotice] = useState('');
  const heading = useRef<HTMLHeadingElement>(null);
  const turn = useRef<TurnExport>(null);
  const history = useHistory();
  const complete = tournament?.phase === TournamentPhase.complete;
  const orientation = tournament
    ? complete
      ? 'champion'
      : `${tournament.matchIndex}:${turnIndex(tournament)}`
    : 'setup';
  useEffect(() => {
    heading.current?.focus();
    if (tournament && !complete) {
      const match = tournament.matches[tournament.matchIndex];
      const player = match?.players[turnIndex(tournament)];
      if (player !== undefined) publish(`Now playing: ${tournament.players[player]}`);
    }
  }, [orientation]);

  function showNotice(text: string): void {
    setNotice(text);
    publish(text);
  }
  function start(): void {
    const error = nameError(names);
    if (error) {
      showNotice(error);
      return;
    }
    const codes: string[] = [];
    for (let i = 0; i < names.length - 1; i += 1) {
      const size = matchRound(names.length, i).size;
      let code = freshBoardCode(size);
      // A repeated random draw still produces a unique deal within this bracket.
      while (codes.includes(code))
        code = boardCode(size, ((parseBoardCode(code)?.seed ?? 1) % SEED_MAX) + 1);
      codes.push(code);
    }
    const next = createTournament(names, codes);
    setNames(next.players);
    setTournament(next);
    setNotice('');
  }
  function finish(result: Result): void {
    if (!tournament) return;
    const next = finishTurn(tournament, result);
    setTournament(next);
    if (next.phase === TournamentPhase.complete) {
      history.save(next);
      const champion = next.matches.at(-1)?.winner;
      publish(
        `Champion: ${champion === undefined || champion === null ? '' : next.players[champion]}`,
      );
    }
  }
  function accept(data: TournamentDocument): void {
    setNames(data.names);
    setSnapshot(data.snapshot);
    setTournament(data.tournament);
    setRevision((value) => value + 1);
    if (data.tournament?.phase === TournamentPhase.complete) history.save(data.tournament);
    showNotice('Loaded tournament.');
  }
  const [revision, setRevision] = useState(0);
  function load(): void {
    const result = decodeTournament(json);
    if (!result.data) {
      showNotice(result.error);
      return;
    }
    const data = result.data;
    if ((tournament && !complete) || (!tournament && names.some((name) => name.trim())))
      confirm(() => accept(data));
    else accept(data);
  }
  function exportCurrent(): void {
    setJson(
      encodeTournament({
        names,
        tournament,
        snapshot:
          tournament?.phase === TournamentPhase.playing
            ? (turn.current?.exportTurn() ?? null)
            : null,
      }),
    );
  }
  const champion = tournament?.matches.at(-1)?.winner;
  return (
    <section className="tournament">
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      {!tournament && <TournamentSetup names={names} change={setNames} start={start} />}
      {tournament && (
        <>
          {complete ? (
            <p className="champion">
              Champion:{' '}
              {champion === null || champion === undefined ? '' : tournament.players[champion]}
            </p>
          ) : (
            <>
              <TournamentPlay
                key={`${revision}:${tournament.matchIndex}:${turnIndex(tournament)}`}
                ref={turn}
                tournament={tournament}
                snapshot={snapshot}
                publish={publish}
                finish={finish}
                started={() => {
                  setTournament(startTurn(tournament));
                  heading.current?.focus();
                }}
              />
              <div className="tournament-actions">
                {tournament.phase === TournamentPhase.turnDone && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setSnapshot(null);
                      setTournament(nextTurn(tournament));
                    }}
                  >
                    Next turn
                  </button>
                )}
                {tournament.phase === TournamentPhase.matchDone && (
                  <button
                    className="control"
                    type="button"
                    onClick={() => {
                      setSnapshot(null);
                      setTournament(nextMatch(tournament));
                    }}
                  >
                    Next match
                  </button>
                )}
                <button className="control" type="button" onClick={() => confirm(back)}>
                  Leave tournament
                </button>
              </div>
            </>
          )}
          <Bracket tournament={tournament} />
        </>
      )}
      {(!tournament || complete) && (
        <button
          className="control"
          type="button"
          onClick={() => {
            if (!tournament && names.some((name) => name.trim())) confirm(back);
            else back();
          }}
        >
          Back to game
        </button>
      )}
      <section className="tournament-exchange" aria-label="Tournament exchange">
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          className="control"
          id="tournament-json"
          value={json}
          maxLength={TOURNAMENT_MAX_BYTES}
          onChange={(event) => setJson(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button className="control" type="button" onClick={exportCurrent}>
            Export tournament
          </button>
          <button
            className="control"
            type="button"
            onClick={load}
            aria-describedby="tournament-notice"
          >
            Load tournament
          </button>
        </div>
        <p id="tournament-notice">{notice}</p>
      </section>
      {!tournament && (
