            type="button"
            onClick={load}
            aria-describedby="tournament-notice"
          >
            Load tournament
          </button>
        </div>
        <p id="tournament-notice">{notice}</p>
      </section>
      {!tournament && (
        <section className="past-tournaments">
          <h3>Past tournaments</h3>
          {history.blocked && <p>Progress won't be saved on this device.</p>}
          {history.items.length === 0 && <p>No finished tournaments yet.</p>}
          <ol>
            {history.items.map((item, i) => {
